import {expect,test} from "bun:test";
import {Database} from "bun:sqlite";
import Ajv from "ajv";
import fixture from "../../🧫️fixtures/🪶️sqlite/🔣️.json";
import lawsSchema from "../../🧫️fixtures/🪶️sqlite/🧬️schema/🔣️.json";
import nativeSchema from "../../🔣️.json";
import artifactSchema from "../../../🔣️.json";
import diffSchema from "../../../🔺️diff/🔣️.json";
import replaceSourceSchema from "../../../🧬️mutations/🖼️replace-source/🧬️schema/🔣️.json";
import childSchema from "../../../../../../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store/🪆️child/🧬️schema/🔣️.json";
import ioSchema from "../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🧬️schema/🔣️.json";
import references from "../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🧬️schema/🔗️reference/🧫️fixtures/🔣️.json";
import * as owner from "../../🟦️.ts";
import {binary64,type Binary64} from "../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🔢️ieee754/🟦️.ts";
import {exportSqliteDatabase,importSqliteDatabase,type SqliteDatabase} from "../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts";
import type {ArtifactSqliteOptions} from "../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🧩️artifact/🟦️.ts";
type Frame={x:Binary64;y:Binary64;width:Binary64;height:Binary64};
type Snapshot=Omit<owner.PresentationSnapshot,"source"|"tiles">&{source:{src:string;kind:string;frame:Frame;sourceAspect?:Binary64;pdfPage?:number};tiles:{id:string;name:string;crop:Frame}[]};
const own=owner as unknown as {PRESENTATION_SQLITE_SCHEMA:string;presentationSnapshotToSqliteDatabase:(snapshot:Snapshot,options?:ArtifactSqliteOptions)=>Promise<SqliteDatabase>;presentationSnapshotFromSqliteDatabase:(database:SqliteDatabase,options?:ArtifactSqliteOptions)=>Promise<Snapshot>};
const frame=(value:{x:number;y:number;width:number;height:number}):Frame=>({x:binary64(value.x),y:binary64(value.y),width:binary64(value.width),height:binary64(value.height)});
const snapshot=():Snapshot=>{const value=structuredClone(fixture.snapshot);return{...value,source:{...value.source,frame:frame(value.source.frame),sourceAspect:binary64(value.source.sourceAspect)},tiles:value.tiles.map(tile=>({...tile,crop:frame(tile.crop)}))}};
const bytes=async(value:Snapshot):Promise<Uint8Array>=>exportSqliteDatabase(await own.presentationSnapshotToSqliteDatabase(value));
const restore=async(value:Uint8Array,options:ArtifactSqliteOptions={}):Promise<Snapshot>=>own.presentationSnapshotFromSqliteDatabase(await importSqliteDatabase(value),options);
test("Presentation independent native JSON schema requires the actual u32 page width",()=>{const ajv=new Ajv({strict:false,validateFormats:false}).addSchema(ioSchema).addSchema(childSchema).addSchema(nativeSchema);expect(ajv.validate(nativeSchema,fixture.snapshot)).toBe(true);expect(ajv.validate(nativeSchema,{...fixture.snapshot,source:{...fixture.snapshot.source,pdfPage:4294967296}})).toBe(false)});
test("Presentation public native parser requires the actual u32 page width",()=>{expect(owner.parsePresentationSnapshot(fixture.snapshot)).toEqual(fixture.snapshot);expect(()=>owner.parsePresentationSnapshot({...fixture.snapshot,source:{...fixture.snapshot.source,pdfPage:4294967296}})).toThrow()});
test("Presentation independent artifact diff and mutation schemas retain the same u32 page domain",()=>{const ajv=new Ajv({strict:false,validateFormats:false}).addSchema(ioSchema).addSchema(childSchema).addSchema(artifactSchema);for(const [schema,value,overflow]of[[artifactSchema,fixture.snapshot,{...fixture.snapshot,source:{...fixture.snapshot.source,pdfPage:4294967296}}],[diffSchema,{source:fixture.snapshot.source},{source:{...fixture.snapshot.source,pdfPage:4294967296}}],[replaceSourceSchema,{newSource:fixture.snapshot.source},{newSource:{...fixture.snapshot.source,pdfPage:4294967296}}]]as const){expect(ajv.validate(schema,value)).toBe(true);expect(ajv.validate(schema,overflow)).toBe(false)}});
test("Presentation neutral fields and controls agree with independent JSON schema",()=>{const ajv=new Ajv({strict:false,validateFormats:false}).addSchema(ioSchema).addSchema(childSchema).addSchema(nativeSchema);expect(ajv.validate(lawsSchema,fixture)).toBe(true);expect(ajv.validate(nativeSchema,{...fixture.snapshot,extra:0})).toBe(false)});
test("Presentation snapshot exposes its handwritten relational owner",()=>{expect(Object.hasOwn(owner,"presentationSnapshotToSqliteDatabase")).toBe(true);expect(Object.hasOwn(owner,"presentationSnapshotFromSqliteDatabase")).toBe(true)});
test("Presentation handcrafted SQL exposes explicit geometry and child reference columns",async()=>{const sql=await Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url)).text(),db=new Database(":memory:");try{db.run(sql);expect(db.query("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name").all()).toEqual(["presentation_child","presentation_document","presentation_source","presentation_tile"].map(name=>({name})));expect(db.query("PRAGMA table_info(presentation_source)").all().map(row=>(row as {name:string}).name)).toContain("source_aspect_bits");expect(db.query("PRAGMA foreign_key_list(presentation_child)").all().length).toBe(1)}finally{db.close()}});
test("Presentation complete files retain duplicate tiles and literal composed references",async()=>{const expected=snapshot(),data=await bytes(expected),db=Database.deserialize(data,{safeIntegers:true});try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query("SELECT tile_id,name FROM presentation_tile ORDER BY ordinal").all()).toEqual(expected.tiles.map(tile=>({tile_id:tile.id,name:tile.name})));expect(db.query("SELECT slot,child_id,artifact_id FROM presentation_child ORDER BY slot").all()).toEqual([{slot:"animation",child_id:expected.animation.childId,artifact_id:expected.animation.target.artifactId},{slot:"presentation",child_id:expected.presentation.childId,artifact_id:expected.presentation.target.artifactId}]);expect(await restore(data)).toEqual(expected)}finally{db.close()}});
test("Presentation optional numeric absence and zero remain distinct from NaN",async()=>{for(const optional of[false,true]){const expected=snapshot();if(optional){expected.source.sourceAspect={bits:0x7ff0000000000001n};expected.source.pdfPage=0}else{delete expected.source.sourceAspect;delete expected.source.pdfPage}const db=Database.deserialize(await bytes(expected),{safeIntegers:true});try{expect(db.query("SELECT source_aspect,source_aspect_bits,source_aspect_class,pdf_page FROM presentation_source").get()).toEqual(optional?{source_aspect:null,source_aspect_bits:0x7ff0000000000001n,source_aspect_class:"nan",pdf_page:0n}:{source_aspect:null,source_aspect_bits:null,source_aspect_class:null,pdf_page:null});expect(await restore(new Uint8Array(db.serialize()))).toEqual(expected)}finally{db.close()}}});
for(const hex of fixture.binary64Words)test("Presentation exact binary64 geometry word "+hex,async()=>{const expected=snapshot(),bits=BigInt("0x"+hex);for(const key of["x","y","width","height"]as const){expected.source.frame[key]={bits};expected.tiles[0]!.crop[key]={bits}}expected.source.sourceAspect={bits};const db=Database.deserialize(await bytes(expected),{safeIntegers:true});try{const independent=Buffer.alloc(8);independent.writeBigUInt64BE(bits);const number=independent.readDoubleBE(),kind=Number.isNaN(number)?"nan":number===Infinity?"positiveInfinity":number===-Infinity?"negativeInfinity":"finite";expect(db.query("SELECT x_bits,x_class FROM presentation_source").get()).toEqual({x_bits:BigInt.asIntN(64,bits),x_class:kind});expect(await restore(new Uint8Array(db.serialize()))).toEqual(expected)}finally{db.close()}});
test("Presentation every child slot retains shared empty and reserved reference components",async()=>{for(const reference of references.references){const expected=snapshot();expected.presentation.target=structuredClone(reference);expected.animation.target=structuredClone(reference);expect(await restore(await bytes(expected))).toEqual(expected)}});
test("Presentation independent semantic edits renumber surrogates and preserve ordered tiles",async()=>{const expected=snapshot(),db=Database.deserialize(await bytes(expected));try{db.run("UPDATE presentation_document SET schema='edited'");db.run("UPDATE presentation_tile SET id=id+99,name='renamed'");db.run("UPDATE presentation_child SET id=id+99,artifact_id='new target'");expected.schema="edited";for(const tile of expected.tiles)tile.name="renamed";expected.presentation.target.artifactId="new target";expected.animation.target.artifactId="new target";expect(await restore(new Uint8Array(db.serialize()))).toEqual(expected)}finally{db.close()}});
test("Presentation independent malformed ownership geometry and ordinals refuse",async()=>{const data=await bytes(snapshot());for(const sql of fixture.malformedSql){const db=Database.deserialize(data);try{db.run("PRAGMA ignore_check_constraints=ON");db.run(sql);await expect(restore(new Uint8Array(db.serialize()))).rejects.toThrow()}finally{db.close()}}});
test("Presentation typed word and native integer widths refuse before ownership",async()=>{const invalid=snapshot();invalid.source.pdfPage=4294967296;await expect(own.presentationSnapshotToSqliteDatabase(invalid)).rejects.toThrow();const invalidWord=snapshot();invalidWord.tiles[0]!.crop.width={bits:18446744073709551616n};await expect(own.presentationSnapshotToSqliteDatabase(invalidWord)).rejects.toThrow();const extra={...snapshot(),extra:true};await expect(own.presentationSnapshotToSqliteDatabase(extra)).rejects.toThrow()});
test("Presentation caller budgets bound real complete entities and values",async()=>{const expected=snapshot();await expect(own.presentationSnapshotToSqliteDatabase(expected,{maxRows:5})).rejects.toThrow();const db=await own.presentationSnapshotToSqliteDatabase(expected);await expect(own.presentationSnapshotFromSqliteDatabase(db,{maxValueBytes:1})).rejects.toThrow();await expect(exportSqliteDatabase(db,{maxFileBytes:fixture.control.tinyFileBytes})).rejects.toThrow();expected.source.src="😀".repeat(fixture.control.largeTextBytes);await expect(own.presentationSnapshotToSqliteDatabase(expected,{maxValueBytes:fixture.control.maxOwnedBytes})).rejects.toThrow()});
for(const phase of["projectSnapshot","reconstructSnapshot"]as const)test("Presentation cancellation interrupts "+phase+" within owned tile traversal",async()=>{const expected=snapshot();expected.tiles=Array.from({length:fixture.control.collectionLength},()=>structuredClone(expected.tiles[0]!));const database=await own.presentationSnapshotToSqliteDatabase(expected);const c=new AbortController();let reached=false;const options:ArtifactSqliteOptions={signal:c.signal,onProgress:event=>{if(event.phase===phase&&event.completed>=256){reached=true;c.abort()}}};await expect(phase==="projectSnapshot"?own.presentationSnapshotToSqliteDatabase(expected,options):own.presentationSnapshotFromSqliteDatabase(database,options)).rejects.toHaveProperty("name","AbortError");expect(reached).toBe(true);const initial=new AbortController();initial.abort();await expect(phase==="projectSnapshot"?own.presentationSnapshotToSqliteDatabase(snapshot(),{signal:initial.signal}):own.presentationSnapshotFromSqliteDatabase(database,{signal:initial.signal})).rejects.toHaveProperty("name","AbortError")});

