 const expected=ownedFixture(),initial=new AbortController();initial.abort();await expect(en1995SnapshotToSqliteDatabase(expected,{signal:initial.signal})).rejects.toHaveProperty("name","AbortError");const database=await en1995SnapshotToSqliteDatabase(expected);await expect(en1995SnapshotFromSqliteDatabase(database,{signal:initial.signal})).rejects.toHaveProperty("name","AbortError");expected.members[0]!.actions=Array.from({length:controls.entityCount},()=>({...expected.members[0]!.actions[0]!}));const large=await en1995SnapshotToSqliteDatabase(expected);
